/// Render a month-end statement: every invoice, separated by a blank line,
/// followed by the number the next issued invoice will get.
///
/// Rendering only peeks at the sequence; it never consumes a number.
pub fn render_invoice_statement(invoices: &[Invoice]) -> String {
    let mut out = String::new();
    for invoice in invoices {
        out.push_str(&render_invoice(invoice));
        out.push('\n');
    }
    out.push_str(&format!("NEXT #{}\n", NEXT_INVOICE.load(Ordering::SeqCst)));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn statement_lists_invoices_and_next_number() {
        let first = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let second = Invoice::draft(vec![Line::new("gadget", 250)]).issue();
        let text = render_invoice_statement(&[first.clone(), second.clone()]);
        let expected = format!(
            "{}\n{}\nNEXT #{}\n",
            render_invoice(&first),
            render_invoice(&second),
            second.number + 1
        );
        assert_eq!(text, expected);
    }

    #[test]
    fn rendering_a_statement_does_not_consume_a_number() {
        let invoice = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let before = render_invoice_statement(&[invoice.clone()]);
        let after = render_invoice_statement(&[invoice]);
        assert_eq!(before, after);
    }

    #[test]
    fn empty_statement_only_reports_next_number() {
        let text = render_invoice_statement(&[]);
        assert_eq!(text, format!("NEXT #{}\n", NEXT_INVOICE.load(Ordering::SeqCst)));
    }

